-- Customer rewards, vouchers, offers and notification foundation.
create type public.discount_kind as enum ('percentage', 'fixed');
create type public.customer_order_status as enum ('pending', 'completed', 'cancelled', 'refunded');
create type public.voucher_status as enum ('available', 'redeemed', 'expired', 'cancelled');
create table public.reward_programs (id uuid primary key default gen_random_uuid(), business_id uuid not null unique references public.businesses(id) on delete cascade, name text not null default 'Loyalty rewards', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reward_tiers (id uuid primary key default gen_random_uuid(), program_id uuid not null references public.reward_programs(id) on delete cascade, order_number integer not null check(order_number>0), discount_kind public.discount_kind not null default 'percentage', discount_value numeric(10,2) not null check(discount_value>0), min_order_amount numeric(12,2) not null default 0 check(min_order_amount>=0), validity_days integer not null default 30 check(validity_days between 1 and 3650), is_active boolean not null default true, created_at timestamptz not null default now(), unique(program_id,order_number), check(discount_kind<>'percentage' or discount_value<=100));
create table public.customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, full_name text, email text, phone text, marketing_consent boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(email is not null or phone is not null));
create unique index customers_business_email_unique on public.customers(business_id,lower(email)) where email is not null;
create unique index customers_business_phone_unique on public.customers(business_id,phone) where phone is not null;
create table public.customer_orders (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, order_number integer not null check(order_number>0), order_amount numeric(12,2) not null check(order_amount>=0), currency_code text not null default 'INR', status public.customer_order_status not null default 'pending', completed_at timestamptz, created_at timestamptz not null default now(), unique(business_id,customer_id,order_number));
create index customer_orders_customer_completed_idx on public.customer_orders(customer_id,status,completed_at desc);
create table public.promotional_offers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, location_id uuid references public.locations(id) on delete set null, title text not null, description text, discount_kind public.discount_kind not null default 'percentage', discount_value numeric(10,2) not null check(discount_value>0), min_order_amount numeric(12,2) not null default 0 check(min_order_amount>=0), starts_at timestamptz not null default now(), expires_at timestamptz not null, is_daily_offer boolean not null default false, usage_limit integer check(usage_limit is null or usage_limit>0), per_customer_limit integer not null default 1 check(per_customer_limit>0), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(expires_at>starts_at), check(discount_kind<>'percentage' or discount_value<=100));
create index promotional_offers_business_active_idx on public.promotional_offers(business_id,is_active,starts_at,expires_at);
create table public.customer_vouchers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, reward_tier_id uuid references public.reward_tiers(id) on delete set null, promotional_offer_id uuid references public.promotional_offers(id) on delete set null, code text not null unique, title text not null, discount_kind public.discount_kind not null, discount_value numeric(10,2) not null check(discount_value>0), min_order_amount numeric(12,2) not null default 0 check(min_order_amount>=0), status public.voucher_status not null default 'available', expires_at timestamptz not null, redeemed_at timestamptz, created_at timestamptz not null default now(), check(discount_kind<>'percentage' or discount_value<=100), check(reward_tier_id is not null or promotional_offer_id is not null));
create index customer_vouchers_wallet_idx on public.customer_vouchers(customer_id,status,expires_at);
create table public.push_subscriptions (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, endpoint text not null unique, p256dh text not null, auth_secret text not null, user_agent text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.customer_notifications (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, customer_id uuid not null references public.customers(id) on delete cascade, notification_type text not null check(notification_type in ('daily_offer','voucher_expiry','voucher_unlocked','business_announcement')), title text not null, body text not null, payload jsonb not null default '{}'::jsonb, scheduled_for timestamptz not null default now(), sent_at timestamptz, read_at timestamptz, created_at timestamptz not null default now());
create index customer_notifications_due_idx on public.customer_notifications(scheduled_for) where sent_at is null;
alter table public.reward_programs enable row level security;
alter table public.reward_tiers enable row level security;
alter table public.customers enable row level security;
alter table public.customer_orders enable row level security;
alter table public.promotional_offers enable row level security;
alter table public.customer_vouchers enable row level security;
alter table public.push_subscriptions enable row level security;
alter table public.customer_notifications enable row level security;
create policy "Business admins manage reward programs" on public.reward_programs for all to authenticated using(public.has_business_role(business_id,array['owner','admin']::public.business_member_role[])) with check(public.has_business_role(business_id,array['owner','admin']::public.business_member_role[]));
create policy "Business admins manage reward tiers" on public.reward_tiers for all to authenticated using(exists(select 1 from public.reward_programs rp where rp.id=program_id and public.has_business_role(rp.business_id,array['owner','admin']::public.business_member_role[]))) with check(exists(select 1 from public.reward_programs rp where rp.id=program_id and public.has_business_role(rp.business_id,array['owner','admin']::public.business_member_role[])));
create policy "Business managers read customers" on public.customers for select to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[]));
create policy "Business managers read customer orders" on public.customer_orders for select to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[]));
create policy "Business admins manage promotional offers" on public.promotional_offers for all to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[])) with check(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[]));
create policy "Business managers read customer vouchers" on public.customer_vouchers for select to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[]));
create policy "Business admins read push subscriptions" on public.push_subscriptions for select to authenticated using(public.has_business_role(business_id,array['owner','admin']::public.business_member_role[]));
create policy "Business managers read customer notifications" on public.customer_notifications for select to authenticated using(public.has_business_role(business_id,array['owner','admin','manager']::public.business_member_role[]));
grant select,insert,update,delete on public.reward_programs,public.reward_tiers,public.promotional_offers to authenticated;
grant select on public.customers,public.customer_orders,public.customer_vouchers,public.push_subscriptions,public.customer_notifications to authenticated;
